mapper.update:
UPDATE lunaerp_baseinfo_supplier_contact
SET deleted = 0,
    updater = #{updater},
    update_time = #{updateTime}
WHERE supplier_id = #{supplierId}
  AND deleted = 1
  AND tenant_id = #{tenantId}

mapper.delete:
DELETE FROM lunaerp_baseinfo_supplier_contact
WHERE supplier_id = #{supplierId}
  AND tenant_id = #{tenantId}
